keyframes.css:
@keyframes shimmer { 
  100% { transform: translate(100%); }
}

@keyframes pill-edge-glow { 
  0%, 100% { box-shadow: rgba(15, 21, 29, 0.4) 0px 8px 20px -8px; }
  50% { box-shadow: rgba(255, 255, 255, 0.12) 0px 0px 20px 2px, rgba(15, 21, 29, 0.4) 0px 8px 20px -8px; }
}

@keyframes social-proof-gradient-float { 
  0% { background-image: linear-gradient(rgb(255, 249, 246) 0px, rgb(255, 249, 246) 40px, rgb(255, 141, 105) calc(100% - 190px), rgb(255, 141, 105) 100%); }
  25% { background-image: linear-gradient(rgb(255, 249, 246) 0px, rgb(255, 249, 246) 55px, rgb(255, 141, 105) calc(100% - 215px), rgb(255, 141, 105) 100%); }
  50% { background-image: linear-gradient(rgb(255, 249, 246) 0px, rgb(255, 249, 246) 70px, rgb(255, 141, 105) calc(100% - 175px), rgb(255, 141, 105) 100%); }
  75% { background-image: linear-gradient(rgb(255, 249, 246) 0px, rgb(255, 249, 246) 55px, rgb(255, 141, 105) calc(100% - 200px), rgb(255, 141, 105) 100%); }
  100% { background-image: linear-gradient(rgb(255, 249, 246) 0px, rgb(255, 249, 246) 40px, rgb(255, 141, 105) calc(100% - 190px), rgb(255, 141, 105) 100%); }
}

@keyframes illus-float { 
  0%, 100% { transform: translate(170px) rotate(-2deg) translateY(0px); }
  50% { transform: translate(170px) rotate(-2deg) translateY(-12px); }
}

@keyframes hero-fade-up { 
  0% { opacity: 0; transform: translateY(20px); }
  100% { opacity: 1; transform: translateY(0px); }
}

@keyframes intro-blob-warm { 
  0%, 100% { transform: translate(0px); }
  50% { transform: translate(60px, 40px); }
}

@keyframes intro-blob-cool { 
  0%, 100% { transform: translate(0px); }
  50% { transform: translate(-50px, -30px); }
}

@keyframes intro-logo-in { 
  0% { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: translateY(0px); }
}

@keyframes intro-reel-fade { 
  0% { opacity: 0; transform: translateY(6px); }
  20% { opacity: 1; transform: translateY(0px); }
  80% { opacity: 1; transform: translateY(0px); }
  100% { opacity: 0; transform: translateY(-6px); }
}

@keyframes intro-reel { 
  100% { transform: translateY(-100%); }
}

@keyframes nomu-shimmer { 
  0% { background-position: 200% 0px; }
  100% { background-position: -200% 0px; }
}

@keyframes ken-burns { 
  0%, 100% { transform: scale(1) translate(0px); }
  50% { transform: scale(1.06) translateY(-1%); }
}

@keyframes spin { 
  100% { transform: rotate(360deg); }
}

@keyframes ping { 
  75%, 100% { opacity: 0; transform: scale(2); }
}

@keyframes pulse { 
  50% { opacity: 0.5; }
}

@keyframes accordion-down { 
  0% { height: 0px; }
  100% { height: var(--radix-accordion-content-height); }
}

@keyframes accordion-up { 
  0% { height: var(--radix-accordion-content-height); }
  100% { height: 0px; }
}

@keyframes marquee { 
  0% { transform: translate(0px); }
  100% { transform: translateX(calc(-100% - var(--gap))); }
}

@keyframes marquee-vertical { 
  0% { transform: translateY(0px); }
  100% { transform: translateY(calc(-100% - var(--gap))); }
}

@keyframes swipe-out-left { 
  0% { transform: var(--y) translateX(var(--swipe-amount-x)); opacity: 1; }
  100% { transform: var(--y) translateX(calc(var(--swipe-amount-x) - 100%)); opacity: 0; }
}
